package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"net/http"

	"github.com/gin-gonic/gin"
)

var encryptionKey = []byte("0123456789abcdef0123456789abcdef") // 32 bytes for AES-256

func main() {
	router := gin.Default()
	router.POST("/api/v1/decrypt-token", handleDecrypt)
	router.GET("/api/v1/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "healthy"})
	})
	router.Run(":8080")
}

func handleDecrypt(c *gin.Context) {
	var req struct {
		Ciphertext string `json:"ciphertext" binding:"required"`
		IV         string `json:"iv" binding:"required"`
	}

	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request body"})
		return
	}

	ciphertextBytes, err := hex.DecodeString(req.Ciphertext)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid ciphertext hex"})
		return
	}

	ivBytes, err := hex.DecodeString(req.IV)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid iv hex"})
		return
	}

	if len(ivBytes) != aes.BlockSize {
		c.JSON(http.StatusBadRequest, gin.H{"error": "iv must be 16 bytes"})
		return
	}

	if len(ciphertextBytes)%aes.BlockSize != 0 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "ciphertext length must be multiple of block size"})
		return
	}

	plaintext, err := decryptCBC(ciphertextBytes, ivBytes)
	if err != nil {
		// VULNERABILITY: Different error for padding vs other failures
		// This leaks padding validity information
		c.JSON(http.StatusInternalServerError, gin.H{"error": "decryption failed: padding invalid"})
		return
	}

	// Validate token structure after successful decryption
	if !isValidToken(plaintext) {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "invalid token structure"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"message": "token accepted", "user": extractUser(plaintext)})
}

func decryptCBC(ciphertext, iv []byte) ([]byte, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	plaintext := make([]byte, len(ciphertext))
	mode.CryptBlocks(plaintext, ciphertext)

	// PKCS7 unpadding - returns error on invalid padding
	plaintext, err = pkcs7Unpad(plaintext, aes.BlockSize)
	if err != nil {
		return nil, err
	}

	return plaintext, nil
}

func pkcs7Unpad(data []byte, blockSize int) ([]byte, error) {
	if len(data) == 0 {
		return nil, fmt.Errorf("empty data")
	}

	padLen := int(data[len(data)-1])
	if padLen == 0 || padLen > blockSize {
		return nil, fmt.Errorf("invalid padding length: %d", padLen)
	}

	for i := len(data) - padLen; i < len(data); i++ {
		if data[i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding byte at position %d", i)
		}
	}

	return data[:len(data)-padLen], nil
}

func isValidToken(plaintext []byte) bool {
	// Token format: "user:<username>:ts:<timestamp>"
	return len(plaintext) > 5 && string(plaintext[:5]) == "user:"
}

func extractUser(plaintext []byte) string {
	// Extract username from token
	for i := 5; i < len(plaintext); i++ {
		if plaintext[i] == ':' {
			return string(plaintext[5:i])
		}
	}
	return string(plaintext[5:])
}
